SELECT MAX(valid_until)
FROM erp_bookstore_pass
WHERE student_id   = #{studentId}
  AND service_code = #{serviceCode}
  AND revoked_at IS NULL

SELECT COUNT(*)
FROM erp_bookstore_pass_use
WHERE student_id = #{studentId} AND used_date = #{usedDate}

SELECT ISNULL(SUM(total_count), 0)
FROM erp_bookstore_pass
WHERE student_id   = #{studentId}
  AND service_code = #{serviceCode}
  AND revoked_at IS NULL
  AND valid_from  <= #{monthEnd}
  AND valid_until >= #{monthStart}

SELECT 
FROM erp_bookstore_pass
WHERE source = #{source}
  AND ref_no = #{refNo}

SELECT COUNT(*)
FROM erp_bookstore_pass_use
WHERE pass_id = #{passId}
